+  font-family: var(--serif);
+  font-weight: 700;
+  font-size: 3.75rem;
+  line-height: .92;
+  padding-right: .55rem;
+  padding-top: .25rem;
+  color: rgba(26,26,26,.92);
+}
+
+.letter .sig{
+  margin-top: var(--space-6);
