+  background: rgba(245,242,237,.7);
+}
+
+.philosophy .statement h2{
+  margin: 0 0 var(--space-3) 0;
+  font-size: 2.1rem;
+}
+
+.philosophy .statement p{
+  margin: 0;
+  color: rgba(26,26,26,.78);
+  line-height: 1.75;
+}
+
+.services{
+  display: grid;
+  gap: var(--space-6);
+}
+
+.services h2{
+  margin: 0;
+  font-size: clamp(2rem, 3vw, 2.6rem);
+}
+
+.service-list{
+  display: grid;
+  gap: var(--space-4);
+}
+
