+  border-radius: calc(var(--radius) + 6px);
+  background: rgba(26,26,26,.02);
+}
+
+.service-item h3{
+  margin: 0 0 .5rem 0;
+  font-size: 1.6rem;
+}
+.service-item p{
+  margin: 0;
+  line-height: 1.8;
+  color: rgba(26,26,26,.78);
+}
+
+/* Clients */
+.clients-hero{
+  display: grid;
+  gap: var(--space-4);
+  align-items: end;
+}
+
+.clients-hero h1{
+  margin: 0;
+  font-size: clamp(2.6rem, 4.8vw, 4.6rem);
+}
+
+.clients-grid{
+  margin-top: var(--space-6);
+  display: grid;
+  gap: var(--space-4);
+}
+
+.client-card{
+  padding: var(--space-5);
+  border: 1px solid var(--hairline);
+  border-radius: calc(var(--radius) + 8px);
+  background: rgba(245,242,237,.65);
+}
+
+.client-card h2{
+  margin: 0 0 .55rem 0;
+  font-size: 1.5rem;
+}
+
+.client-card p{
+  margin: 0;
+  color: rgba(26,26,26,.76);
+  line-height: 1.7;
+}
+
+/* Contact */
+.contact{
+  min-height: calc(100svh - 84px);
+  display: grid;
+  align-content: center;
+  gap: var(--space-5);
+  padding: var(--space-7) 0;
+}
+
+.contact h1{
+  margin: 0;
+  font-size: clamp(3.6rem, 11vw, 8rem);
+  letter-spacing: -0.06em;
+  line-height: .93;
+}
+
+.contact-links{
+  display: grid;
+  gap: .6rem;
+}
+
+.contact-links a{
+  font-size: 1.2rem;
+  color: rgba(26,26,26,.78);
+  text-decoration: none;
+  width: fit-content;
+}
+
+.contact-links a:hover{ text-decoration: underline; text-underline-offset: .22em; }
+
+/* Footer */
+.footer{
+  padding: var(--space-6) 0;
+  border-top: 1px solid var(--hairline-2);
+  color: rgba(26,26,26,.7);
+}
+.footer .cols{ display: grid; gap: var(--space-4); }
+
+/* Responsive */
+@media (min-width: 860px){
+  .nav{ grid-template-columns: auto 1fr; gap: 2rem; }
+  .nav-links{ display: inline-flex; justify-self: end; }
+  .menu-btn{ display: none; }
+
+  .hero-grid{ grid-template-columns: 1.2fr .8fr; }
+  .media-grid{ grid-template-columns: 1.2fr .8fr; }
+  .media-grid .media:last-child{ grid-column: 1 / -1; min-height: 260px; }
+  .about-grid{ grid-template-columns: .9fr 1.1fr; }
+  .philosophy{ grid-template-columns: 1fr 1fr; }
+
+  .clients-hero{ grid-template-columns: 1.1fr .9fr; }
+  .clients-grid{ grid-template-columns: repeat(3, minmax(0, 1fr)); }
+  .footer .cols{ grid-template-columns: 1fr 1fr; align-items: baseline; }
+}
+
+@media (max-width: 380px){
+  .container, .container-wide{ width: calc(100% - 2 * var(--space-3)); }
+  main{ padding: var(--space-6) 0 var(--space-7); }
+}
+
*** End Patch
