+/* Neweno (Founder Letter) */
+.letter{
+  max-width: var(--reading);
+  margin-inline: auto;
+}
+
+.letter h1{
+  font-size: clamp(2.6rem, 5vw, 4.4rem);
+  margin: 0 0 var(--space-5) 0;
+}
+
+.letter p{
+  margin: 0 0 1.05rem 0;
+  line-height: 1.85;
+  font-size: 1.06rem;
+  color: rgba(26,26,26,.82);
+}
+
+.letter .dropcap::first-letter{
