+
+/* Services */
+.philosophy{
+  display: grid;
+  gap: var(--space-5);
+  align-items: start;
+}
+
+.philosophy h1{
+  font-size: clamp(2.4rem, 4.3vw, 4rem);
+  margin: 0;
+}
+
+.philosophy .statement{
+  padding: var(--space-5);
+  border: 1px solid var(--hairline);
+  border-radius: calc(var(--radius) + 6px);
+  background: rgba(245,242,237,.7);
+}
+
+.philosophy .statement h2{
+  margin: 0 0 var(--space-3) 0;
+  font-size: 2.1rem;
