+
+    qsa('a', overlay).forEach(function(a){
+      a.addEventListener('click', function(){ setOpen(false); });
+    });
+
+    document.addEventListener('keydown', function(e){
+      if(e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') setOpen(false);
